/* ── APP STATE ─────────────────────────────────────────────── */
let state = {
  user:           JSON.parse(localStorage.getItem('cq_user')     || 'null'),
  currentCountry: 'japan',
  quiz:           { difficulty:'easy', current:0, score:0, xp:0, answers:[], questions:[] },
  progress:       JSON.parse(localStorage.getItem('cq_progress') || '{}'),
  attempts:       JSON.parse(localStorage.getItem('cq_attempts') || '[]'),
};

function save() {
  localStorage.setItem('cq_progress', JSON.stringify(state.progress));
  localStorage.setItem('cq_attempts', JSON.stringify(state.attempts));
  if (state.user) localStorage.setItem('cq_user', JSON.stringify(state.user));
}

/* Helper: get questions for a country (fallback to Japan if none) */
function getQuestions(slug) {
  return ALL_QUESTIONS[slug] || ALL_QUESTIONS['japan'];
}